export function indirimliFiyat(fiyat, yuzde) {
  const indirim = fiyat * (yuzde / 100);

  // Kampanya dönemi ise indirmenin yarısını uygula
  if (kampanyaDöndü) {
    return fiyat - (indirim / 2);
  }

  // Normal indirim uygula
  return fiyat - indirim;
}

